'use strict';(()=>{
  const $=s=>document.querySelector(s),cfg=window.SCENARIO,model=LayerEngine.createModel(cfg),scene=$('#scene'),audio=$('#audio');let timer=null,audioURL=null,manual=true,cueCount=0;
  function stop(){clearInterval(timer);timer=null;$('#auto').textContent='开始无声导览';}
  function pause(){stop();audio.pause();manual=true;}
  function full(){scene.setAttribute('viewBox',`0 0 ${cfg.width} ${cfg.height}`);$('#detail').hidden=true;}
  function render(){const s=model.getState(),step=cfg.steps[s.step];$('#title').textContent=step.title;$('#description').textContent=step.text;$('#counter').textContent=`${s.step+1} / ${cfg.steps.length}`;$('#previous').disabled=s.step===0;$('#next').disabled=s.step===cfg.steps.length-1;document.querySelectorAll('[data-group]').forEach(g=>{g.classList.toggle('off',!s.layers[g.dataset.group]);g.setAttribute('aria-hidden',String(!s.layers[g.dataset.group]));});document.querySelectorAll('[data-switch]').forEach(c=>c.checked=s.layers[c.dataset.switch]);$('#evidence').hidden=!s.layers.evidence;if(!s.layers.points){$('#detail').hidden=true;document.querySelectorAll('.point').forEach(p=>p.setAttribute('tabindex','-1'));}else document.querySelectorAll('.point').forEach(p=>p.setAttribute('tabindex','0'));}
  function step(n){model.setStep(n);full();render();}
  cfg.layers.forEach(l=>{const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.switch=l.id;input.onchange=()=>{pause();model.toggle(l.id,input.checked);render();};label.append(input,document.createTextNode(' '+l.name));$('#switches').append(label);});
  cfg.points.forEach(p=>{const ns='http://www.w3.org/2000/svg',g=document.createElementNS(ns,'g'),c=document.createElementNS(ns,'circle'),t=document.createElementNS(ns,'text');g.setAttribute('class','point');g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label','聚焦'+p.name);c.setAttribute('cx',p.x);c.setAttribute('cy',p.y);c.setAttribute('r',22);t.setAttribute('x',p.x);t.setAttribute('y',p.y+57);t.textContent=p.name;g.append(c,t);function focus(){if(!model.getState().layers.points)return;pause();model.select(p.id);const w=500,h=312.5;scene.setAttribute('viewBox',`${Math.max(0,Math.min(cfg.width-w,p.x-w/2))} ${Math.max(0,Math.min(cfg.height-h,p.y-h/2))} ${w} ${h}`);$('#detail').hidden=false;$('#detail').textContent=p.name+'：'+p.note;}g.onclick=focus;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();focus();}};$('#points').append(g);});
  $('#previous').onclick=()=>{pause();step(model.getState().step-1);};$('#next').onclick=()=>{pause();step(model.getState().step+1);};$('#reset').onclick=()=>{pause();step(0);};$('#full').onclick=full;
  $('#auto').onclick=()=>{if(timer){stop();return;}pause();step(0);$('#auto').textContent='暂停导览';timer=setInterval(()=>{const n=model.getState().step+1;if(n>=cfg.steps.length){stop();return;}step(n);},4000);};
  $('#audioFile').onchange=e=>{const f=e.target.files[0];if(!f)return;pause();if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(f);audio.src=audioURL;$('#status').textContent=cueCount?`音频已载入；已有 ${cueCount} 段动作轴。`:'音频已载入；需匹配的动作轴。';};
  $('#cueFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;pause();try{cueCount=model.loadCues(JSON.parse(await f.text()).cues);$('#status').textContent=`已载入 ${cueCount} 段动作轴。`;}catch(error){cueCount=0;try{model.loadCues([]);}catch{}$('#status').textContent='动作轴未接入：'+error.message;}};
  function sync(){if(manual)return;const before=model.getState().step;model.synchronize(audio.currentTime);if(model.getState().step!==before){full();render();}}
  audio.onplay=()=>{stop();manual=false;sync();};audio.ontimeupdate=sync;audio.onseeked=sync;
  $('#download').onclick=()=>{const u=URL.createObjectURL(new Blob([model.serialize()],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='layer-observation.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
  window.addEventListener('pagehide',()=>{pause();if(audioURL)URL.revokeObjectURL(audioURL);});render();
})();
